function parseDuration(input: string): number {
    if (input.length === 0) {
        throw new Error("Invalid input: empty string");
    }

    const regex = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
    const match = input.match(regex);

    if (!match) {
        throw new Error("Invalid input format");
    }

    const [, hStr, mStr, sStr] = match;

    // Ensure at least one unit is present
    if (hStr === undefined && mStr === undefined && sStr === undefined) {
        throw new Error("Invalid input: no time unit found");
    }

    // Convert and validate each captured group
    const h = hStr !== undefined ? parseInt(hStr, 10) : 0;
    const m = mStr !== undefined ? parseInt(mStr, 10) : 0;
    const s = sStr !== undefined ? parseInt(sStr, 10) : 0;

    // Additional sanity checks (non‑negative integers)
    if (isNaN(h) || isNaN(m) || isNaN(s) || h < 0 || m < 0 || s < 0) {
        throw new Error("Invalid numeric value");
    }

    return h * 3600 + m * 60 + s;
}
