type SemVer = {
    major: number;
    minor: number;
    patch: number;
    prerelease: string[] | null;
};

function parseSemVer(v: string): SemVer {
    const regex = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
    const m = v.match(regex);
    if (!m) throw new Error(`Invalid version: ${v}`);

    const major = Number(m[1]);
    const minor = Number(m[2]);
    const patch = Number(m[3]);

    const prereleaseRaw = m[4];
    let prerelease: string[] | null = null;
    if (prereleaseRaw !== undefined) {
        prerelease = prereleaseRaw.split('.');
        // validate each identifier
        for (const id of prerelease) {
            if (id.length === 0) throw new Error(`Invalid prerelease identifier in ${v}`);
            // numeric identifier must not have leading zeros
            if (/^\d+$/.test(id) && id.length > 1 && id.startsWith('0')) {
                throw new Error(`Invalid numeric prerelease identifier with leading zero in ${v}`);
            }
        }
    }

    // build metadata is ignored, but still validated by regex
    return { major, minor, patch, prerelease };
}

function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
    const aNum = /^\d+$/.test(a);
    const bNum = /^\d+$/.test(b);
    if (aNum && bNum) {
        const an = Number(a);
        const bn = Number(b);
        return an < bn ? -1 : an > bn ? 1 : 0;
    }
    if (aNum && !bNum) return -1; // numeric < alphanumeric
    if (!aNum && bNum) return 1;
    // both alphanumeric
    return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Compare two semantic version strings.
 * @returns -1 if a < b, 0 if equal, 1 if a > b
 * @throws Error for invalid version strings
 */
export function compareSemver(a: string, b: string): -1 | 0 | 1 {
    const av = parseSemVer(a);
    const bv = parseSemVer(b);

    if (av.major !== bv.major) return av.major < bv.major ? -1 : 1;
    if (av.minor !== bv.minor) return av.minor < bv.minor ? -1 : 1;
    if (av.patch !== bv.patch) return av.patch < bv.patch ? -1 : 1;

    const aPre = av.prerelease;
    const bPre = bv.prerelease;

    // No prerelease => higher precedence than any prerelease
    if (aPre === null && bPre === null) return 0;
    if (aPre === null) return 1;
    if (bPre === null) return -1;

    // Both have prerelease: compare identifier by identifier
    const len = Math.max(aPre.length, bPre.length);
    for (let i = 0; i < len; i++) {
        const aId = aPre[i];
        const bId = bPre[i];
        if (aId === undefined) return -1; // a has fewer identifiers -> lower precedence
        if (bId === undefined) return 1;  // b has fewer identifiers -> lower precedence
        const cmp = compareIdentifiers(aId, bId);
        if (cmp !== 0) return cmp;
    }
    return 0;
}
