function buildOrder(deps: Record<string, string[]>): string[] {
    // Collect all nodes
    const nodes = new Set<string>();
    for (const pkg of Object.keys(deps)) {
        nodes.add(pkg);
        for (const dep of deps[pkg]) nodes.add(dep);
    }

    // Build adjacency (reverse edges) and indegree map
    const adj = new Map<string, string[]>(); // node -> list of dependents
    const indeg = new Map<string, number>();
    for (const n of nodes) {
        adj.set(n, []);
        indeg.set(n, 0);
    }

    for (const [pkg, depList] of Object.entries(deps)) {
        for (const dep of depList) {
            // edge dep -> pkg
            adj.get(dep)!.push(pkg);
            indeg.set(pkg, indeg.get(pkg)! + 1);
        }
    }

    // Simple binary min‑heap for strings
    class MinHeap {
        private data: string[] = [];
        constructor(private compare: (a: string, b: string) => number) {}
        push(item: string) {
            this.data.push(item);
            this.bubbleUp(this.data.length - 1);
        }
        pop(): string | undefined {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const end = this.data.pop()!;
            if (this.data.length > 0) {
                this.data[0] = end;
                this.sinkDown(0);
            }
            return top;
        }
        size(): number { return this.data.length; }
        private bubbleUp(idx: number) {
            const item = this.data[idx];
            while (idx > 0) {
                const parentIdx = (idx - 1) >> 1;
                const parent = this.data[parentIdx];
                if (this.compare(item, parent) >= 0) break;
                this.data[parentIdx] = item;
                this.data[idx] = parent;
                idx = parentIdx;
            }
        }
        private sinkDown(idx: number) {
            const length = this.data.length;
            const item = this.data[idx];
            while (true) {
                let leftIdx = idx * 2 + 1;
                let rightIdx = leftIdx + 1;
                let swapIdx: number | null = null;

                if (leftIdx < length) {
                    const left = this.data[leftIdx];
                    if (this.compare(left, item) < 0) swapIdx = leftIdx;
                }
                if (rightIdx < length) {
                    const right = this.data[rightIdx];
                    if (
                        (swapIdx === null && this.compare(right, item) < 0) ||
                        (swapIdx !== null && this.compare(right, this.data[swapIdx]) < 0)
                    ) {
                        swapIdx = rightIdx;
                    }
                }
                if (swapIdx === null) break;
                this.data[idx] = this.data[swapIdx];
                this.data[swapIdx] = item;
                idx = swapIdx;
            }
        }
    }

    const heap = new MinHeap((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    for (const n of nodes) {
        if (indeg.get(n)! === 0) heap.push(n);
    }

    const result: string[] = [];
    while (heap.size() > 0) {
        const cur = heap.pop()!;
        result.push(cur);
        for (const nxt of adj.get(cur)!) {
            indeg.set(nxt, indeg.get(nxt)! - 1);
            if (indeg.get(nxt)! === 0) heap.push(nxt);
        }
    }

    if (result.length !== nodes.size) {
        throw new Error("cycle detected");
    }
    return result;
}
