function parseCsvLine(line: string): string[] {
  if (line.length === 0) return [];

  const result: string[] = [];
  let field = "";
  let inQuotes = false;
  let i = 0;
  const len = line.length;

  while (i <= len) {
    const c = i < len ? line[i] : null;

    if (!inQuotes) {
      if (c === "," || c === null) {
        result.push(field);
        field = "";
        i++;
        continue;
      }

      if (c === '"') {
        // start of a quoted field only if field is currently empty
        if (field.length === 0) {
          inQuotes = true;
          i++;
          continue;
        } else {
          // stray quote inside an unquoted field – treat as literal
          field += c;
          i++;
          continue;
        }
      }

      // regular character
      field += c!;
      i++;
    } else {
      // inside quoted field
      if (c === '"') {
        // escaped quote?
        if (i + 1 < len && line[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          // closing quote
          inQuotes = false;
          i++;
          // after a closing quote only a comma or end of line is allowed
          if (i < len) {
            const next = line[i];
            if (next !== ",") {
              throw new Error("Invalid character after closing quote");
            }
          }
        }
      } else {
        // any other character inside quotes
        field += c!;
        i++;
      }
    }
  }

  if (inQuotes) {
    throw new Error("Unterminated quoted field");
  }

  return result;
}
