type Parsed = {
    major: number;
    minor: number;
    patch: number;
    prerelease?: string[];
};

function parseVersion(v: string): Parsed {
    const semverRegex = /^(?<core>\d+\.\d+\.\d+)(?:-(?<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+(?<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
    const match = v.match(semverRegex);
    if (!match || !match.groups) throw new Error(`Invalid version: ${v}`);

    const coreParts = match.groups.core.split('.');
    const [majorStr, minorStr, patchStr] = coreParts;

    // leading zero check for core numeric identifiers
    for (const part of coreParts) {
        if (!/^(0|[1-9]\d*)$/.test(part)) {
            throw new Error(`Invalid numeric identifier in core: ${part}`);
        }
    }

    const major = Number(majorStr);
    const minor = Number(minorStr);
    const patch = Number(patchStr);

    let prerelease: string[] | undefined;
    if (match.groups.prerelease !== undefined) {
        prerelease = match.groups.prerelease.split('.').map(id => {
            if (id.length === 0) throw new Error(`Empty prerelease identifier`);
            // validate characters
            if (!/^[0-9A-Za-z-]+$/.test(id)) {
                throw new Error(`Invalid prerelease identifier: ${id}`);
            }
            // numeric identifier must not have leading zeros
            if (/^\d+$/.test(id) && !/^(0|[1-9]\d*)$/.test(id)) {
                throw new Error(`Invalid numeric prerelease identifier: ${id}`);
            }
            return id;
        });
    }

    return { major, minor, patch, prerelease };
}

function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
    const aNum = /^\d+$/.test(a);
    const bNum = /^\d+$/.test(b);

    if (aNum && bNum) {
        const diff = Number(a) - Number(b);
        return diff < 0 ? -1 : diff > 0 ? 1 : 0;
    }

    if (aNum && !bNum) return -1; // numeric < alphanumeric
    if (!aNum && bNum) return 1;  // alphanumeric > numeric

    // both alphanumeric: lexical ASCII comparison
    return a < b ? -1 : a > b ? 1 : 0;
}

export function compareSemver(a: string, b: string): -1 | 0 | 1 {
    const A = parseVersion(a);
    const B = parseVersion(b);

    if (A.major !== B.major) return A.major < B.major ? -1 : 1;
    if (A.minor !== B.minor) return A.minor < B.minor ? -1 : 1;
    if (A.patch !== B.patch) return A.patch < B.patch ? -1 : 1;

    const aPre = A.prerelease;
    const bPre = B.prerelease;

    // No prerelease => release version
    if (!aPre && !bPre) return 0;
    if (!aPre && bPre) return 1; // release > prerelease
    if (aPre && !bPre) return -1; // prerelease < release

    // Both have prerelease arrays
    const len = Math.max(aPre!.length, bPre!.length);
    for (let i = 0; i < len; i++) {
        const aId = aPre![i];
        const bId = bPre![i];
        if (aId === undefined) return -1; // shorter set < longer set
        if (bId === undefined) return 1;  // longer set > shorter set
        const comp = compareIdentifiers(aId, bId);
        if (comp !== 0) return comp;
    }

    return 0;
}
