function buildOrder(deps: Record<string, string[]>): string[] {
    // Collect all package names (keys and dependencies)
    const all = new Set<string>();
    for (const pkg in deps) {
        all.add(pkg);
        for (const d of deps[pkg]) all.add(d);
    }

    // Initialise adjacency list (edges from dependency -> dependent) and indegree map
    const adj = new Map<string, string[]>();
    const indegree = new Map<string, number>();
    for (const node of all) {
        adj.set(node, []);
        indegree.set(node, 0);
    }

    // Build graph
    for (const pkg in deps) {
        for (const d of deps[pkg]) {
            adj.get(d)!.push(pkg);
            indegree.set(pkg, indegree.get(pkg)! + 1);
        }
    }

    // Nodes with zero indegree, kept sorted lexicographically
    const zero: string[] = [];
    for (const node of all) {
        if (indegree.get(node)! === 0) zero.push(node);
    }
    zero.sort();

    const result: string[] = [];

    while (zero.length) {
        const node = zero.shift()!; // smallest lexicographic node
        result.push(node);

        for (const neigh of adj.get(node)!) {
            indegree.set(neigh, indegree.get(neigh)! - 1);
            if (indegree.get(neigh) === 0) {
                zero.push(neigh);
            }
        }
        zero.sort(); // maintain lexicographic order
    }

    if (result.length !== all.size) {
        throw new Error('cycle detected');
    }

    return result;
}
