function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let i = 0;
  const len = line.length;

  while (true) {
    // End of line handling (including empty line)
    if (i >= len) {
      // If the line ends with a comma, the loop will have already added an empty field.
      // Otherwise, we need to add a final empty field for an empty line.
      if (len === 0 || line.endsWith(',')) {
        fields.push('');
      }
      break;
    }

    let field = '';

    // Quoted field
    if (line[i] === '"') {
      i++; // skip opening quote
      let closed = false;
      while (i < len) {
        const ch = line[i];
        if (ch === '"') {
          if (i + 1 < len && line[i + 1] === '"') {
            // escaped quote
            field += '"';
            i += 2;
          } else {
            // closing quote
            i++;
            closed = true;
            break;
          }
        } else {
          field += ch;
          i++;
        }
      }
      if (!closed) {
        throw new Error('Unterminated quoted field');
      }
      // After a closing quote only a comma or end of line is allowed
      if (i < len && line[i] !== ',') {
        throw new Error('Invalid character after closing quote');
      }
    } else {
      // Unquoted field
      while (i < len && line[i] !== ',') {
        field += line[i];
        i++;
      }
    }

    fields.push(field);

    // If we are at the end, break
    if (i >= len) {
      break;
    }

    // Current character must be a comma (we already validated after quoted fields)
    i++; // skip comma

    // If the line ends with a comma, add an empty field on next iteration
    if (i >= len) {
      fields.push('');
      break;
    }
  }

  return fields;
}
